90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OID: u8 = 0x06;
111	    const TAG_SEQUENCE: u8 = 0x30;
112	    const TAG_SET: u8 = 0x31;
113	    const TAG_UTC_TIME: u8 = 0x17;
114	    const TAG_GENERALIZED_TIME: u8 = 0x18;
115	
116	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
117	    /// length encodings and truncated data.
118	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
119	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
120	        if tag & 0x1F == 0x1F {
121	            return Err("multi-byte tags are not supported".to_string());
122	        }
123	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
124	        let (len, header_len) = match first_len {
125	            0x00..=0x7F => (first_len as usize, 2),
126	            0x80 => return Err("indefinite length is not valid DER".to_string()),
127	            0xFF => return Err("reserved length byte".to_string()),
128	            long => {
129	                let n = (long & 0x7F) as usize;
130	                if !(1..=4).contains(&n) {
131	                    return Err("length is too large".to_string());
132	                }
133	                let bytes = buf
134	                    .get(2..2 + n)
135	                    .ok_or_else(|| "truncated long length".to_string())?;
136	                if bytes[0] == 0 {
137	                    return Err("non-minimal length encoding".to_string());
138	                }
139	                let mut len = 0usize;
140	                for &b in bytes {
141	                    len = len
142	                        .checked_shl(8)
143	                        .and_then(|l| l.checked_add(b as usize))
144	                        .ok_or_else(|| "length overflow".to_string())?;
145	                }
146	                if len < 0x80 {
147	                    return Err("non-minimal length encoding".to_string());
148	                }
149	                (len, 2 + n)
150	            }
151	        };
152	        let total = header_len
153	            .checked_add(len)
154	            .filter(|&t| t <= buf.len())
155	            .ok_or_else(|| "truncated TLV content".to_string())?;
156	        Ok((
157	            Tlv {
158	                tag,
159	                content: &buf[header_len..total],
160	            },
161	            &buf[total..],
162	        ))
163	    }
164	
165	    fn read_tagged<'a>(
166	        buf: &'a [u8],
167	        tag: u8,
168	        what: &str,
169	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
170	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
171	        if tlv.tag != tag {
172	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
173	        }
174	        Ok((tlv, rest))
175	    }
176	
177	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
178	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
179	        // signatureValue BIT STRING } — and nothing trailing.
180	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
181	        if !rest.is_empty() {
182	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
183	        }
184	
185	        let c = cert.content;
186	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
187	        let (_sig_alg, c) = read_tagged(c, TAG_SEQUENCE, "signatureAlgorithm")?;
188	        let (sig_value, c) = read_tlv(c)?;
189	        if sig_value.tag != TAG_BIT_STRING {
190	            return Err("signature must be a BIT STRING".to_string());
191	        }
192	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
193	            return Err("invalid signature BIT STRING".to_string());
194	        }
195	        if !c.is_empty() {
196	            return Err("trailing data in Certificate".to_string());
197	        }
198	
199	        // TBSCertificate ::= SEQUENCE {
200	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
201	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
202	        let t = tbs.content;
203	        let (first, t2) = read_tlv(t)?;
204	        let t = if first.tag == 0xA0 {
205	            let (version, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
206	            if !vrest.is_empty() || version.content.len() != 1 || version.content[0] > 2 {
207	                return Err("invalid certificate version".to_string());
208	            }
209	            t2
210	        } else {
211	            t // No explicit version: v1 certificate.
212	        };
213	
214	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
215	        let t = t3;
216	        let (_tbs_sig, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
217	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
218	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
219	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
220	        let (spki, mut t) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
221	        check_spki(spki)?;
222	        // Remaining fields (issuerUniqueID, subjectUniqueID, extensions, ...)
223	        // are optional; they must still each be well-formed TLVs.
224	        while !t.is_empty() {
225	            let (_, rest) = read_tlv(t)?;
226	            t = rest;
227	        }
228	
229	        let serial_hex = format_serial(serial.content)?;
230	        let issuer = format_name(issuer)?;
231	        let subject = format_name(subject)?;
232	
233	        let v = validity.content;
234	        let (nb, v2) = read_tlv(v)?;
235	        let (na, v3) = read_tlv(v2)?;
236	        if !v3.is_empty() {
237	            return Err("trailing data in validity".to_string());
238	        }
239	        let not_before = format_time(nb)?;
240	        let not_after = format_time(na)?;
241	
242	        Ok(Cert {
243	            subject,
244	            issuer,
245	            serial_hex,
246	            not_before,
247	            not_after,
248	        })
249	    }
250	
251	    /// SubjectPublicKeyInfo ::= SEQUENCE {
252	    ///   algorithm        AlgorithmIdentifier,
253	    ///   subjectPublicKey BIT STRING }
254	    /// Nothing may be missing and no extra elements may follow.
255	    fn check_spki(spki: Tlv) -> Result<(), String> {
256	        let (alg, rest) = read_tagged(
257	            spki.content,
258	            TAG_SEQUENCE,
259	            "subjectPublicKeyInfo algorithm identifier",
260	        )?;
261	        check_algorithm_identifier(alg)?;
262	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
263	        check_bit_string(key.content, "subjectPublicKey")?;
264	        if !rest.is_empty() {
265	            return Err("trailing data in subjectPublicKeyInfo".to_string());
266	        }
267	        Ok(())
268	    }
269	
270	    /// AlgorithmIdentifier ::= SEQUENCE {
271	    ///   algorithm  OBJECT IDENTIFIER,
272	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
273	    /// The parameters, if present, must be exactly one complete DER TLV;
274	    /// absent parameters and an explicit NULL are both accepted. The
275	    /// parameter content is not interpreted for any particular algorithm.
276	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
277	        let (oid, rest) = read_tagged(alg.content, TAG_OID, "algorithm OID")?;
278	        parse_oid(oid.content).map_err(|e| format!("algorithm OID: {e}"))?;
279	        if rest.is_empty() {
280	            return Ok(());
281	        }
282	        let (_params, after) =
283	            read_tlv(rest).map_err(|e| format!("algorithm parameters: {e}"))?;
284	        if !after.is_empty() {
285	            return Err("multiple algorithm parameters".to_string());
286	        }
287	        Ok(())
288	    }
289	
290	    /// Validate the DER content of a BIT STRING: one leading byte counting
291	    /// unused bits (0..=7), and when the count is nonzero those low bits of
292	    /// the final data byte must all be zero. An empty bit string is only
293	    /// legal with a zero count.
294	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
295	        let unused = *content
296	            .first()
297	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
298	        if unused > 7 {
299	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
300	        }
301	        let data = &content[1..];
302	        if data.is_empty() {
303	            if unused != 0 {
304	                return Err(format!(
305	                    "{what} BIT STRING declares {unused} unused bits but has no data"
306	                ));
307	            }
308	            return Ok(());
309	        }
310	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
311	            return Err(format!(
312	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
313	            ));
314	        }
315	        Ok(())
316	    }
317	
318	    /// Render the serial number as upper-case hex, matching the integer value
319	    /// (a DER sign-padding 0x00 byte is not part of the number).
320	    fn format_serial(content: &[u8]) -> Result<String, String> {
321	        if content.is_empty() {
322	            return Err("empty serial number".to_string());
323	        }
324	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
325	            return Err("non-minimal serial number encoding".to_string());
326	        }
327	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
328	            return Err("non-minimal serial number encoding".to_string());
329	        }
330	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
331	            return Err("negative serial number".to_string());
332	        }
333	        let digits = if content.len() > 1 && content[0] == 0x00 {
334	            &content[1..]
335	        } else {
336	            content
337	        };
338	        let mut s = String::with_capacity(digits.len() * 2);
339	        for b in digits {
340	            write!(s, "{b:02X}").unwrap();
341	        }
342	        if s.is_empty() {
343	            s.push_str("00");
344	        }
345	        Ok(s)
346	    }
347	
348	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
349	    /// multi-valued RDNs joined with '+'). Values of known attribute types
350	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
351	    /// when their tag has a text decoder; a known type carrying any other
352	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
353	    /// name and uses the '#' form carrying the value's full DER encoding in
354	    /// hex. Attributes without a known short name use their dotted OID with
355	    /// the same '#' form.
356	    fn format_name(name: Tlv) -> Result<String, String> {
357	        let mut rdn_buf = name.content;
358	        let mut rdns: Vec<String> = Vec::new();
359	        while !rdn_buf.is_empty() {
360	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
361	            rdn_buf = rest;
362	
363	            let mut atv_buf = set.content;
364	            let mut parts = Vec::new();
365	            while !atv_buf.is_empty() {
366	                let (atv, rest) =
367	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
368	                atv_buf = rest;
369	
370	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
371	                let (value, after_value) = read_tlv(after_oid)?;
372	                if !after_value.is_empty() {
373	                    return Err("trailing data in attribute value".to_string());
374	                }
375	
376	                let oid_arcs = parse_oid(oid.content)?;
377	                match oid_short_name(&oid_arcs) {
378	                    Some(label) => {
379	                        if is_text_value_tag(value.tag) {
380	                            // Supported string type: decode to escaped text.
381	                            // A decode failure (e.g. invalid UTF-8) means the
382	                            // certificate is corrupt; it must not be salvaged
383	                            // by falling back to the hex form.
384	                            let text = decode_attribute_value(value.tag, value.content)?;
385	                            parts.push(format!("{label}={}", escape_value(&text)));
386	                        } else {
387	                            // Known type but a legal value with no text decoder
388	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
389	                            // and show the full original DER encoding as '#'-hex.
390	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
391	                        }
392	                    }
393	                    None => {
394	                        // Unknown attribute type: RFC 4514 requires the form
395	                        // OID=#hex, where the hex is the full DER encoding
396	                        // (tag, length and content) of the attribute value.
397	                        // The value is still validated: a UTF8String must
398	                        // hold valid UTF-8 even when shown as hex.
399	                        if value.tag == 0x0C {
400	                            std::str::from_utf8(value.content)
401	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
402	                        }
403	                        let hex = value_hex(after_oid, after_value);
404	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
405	                    }
406	                }
407	            }
408	            if parts.is_empty() {
409	                return Err("empty RelativeDistinguishedName".to_string());
410	            }
411	            rdns.push(parts.join("+"));
412	        }
413	        rdns.reverse();
414	        Ok(rdns.join(","))
415	    }
416	
417	    /// Uppercase hex of one complete value TLV, sliced straight from the
418	    /// input bytes (`around` ends at `rest`). The original tag and length
419	    /// bytes survive verbatim, including a legal long-form length; nothing is
420	    /// re-encoded and content alone is never emitted.
421	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
422	        let tlv_len = around.len() - rest.len();
423	        let mut hex = String::with_capacity(tlv_len * 2);
424	        for b in &around[..tlv_len] {
425	            write!(hex, "{b:02X}").unwrap();
426	        }
427	        hex
428	    }
429	
430	    /// Tags whose attribute values have a direct text decoding in
431	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
432	    /// legal non-text value for display purposes and is rendered as '#'-hex.
433	    fn is_text_value_tag(tag: u8) -> bool {
434	        matches!(
435	            tag,
436	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
437	        )
438	    }
439	
440	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
441	        if content.is_empty() {
442	            return Err("empty OID".to_string());
443	        }
444	        let mut arcs = Vec::new();
445	        // The first subidentifier encodes the first two arcs as
446	        // 40*first + second and is itself a base-128 quantity, so it can
447	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
448	        let mut i = 0;
449	        let first = read_oid_arc(content, &mut i)?;
450	        match first {
451	            0..=39 => {
452	                arcs.push(0);
453	                arcs.push(first);
454	            }
455	            40..=79 => {
456	                arcs.push(1);
457	                arcs.push(first - 40);
458	            }
459	            _ => {
460	                arcs.push(2);
461	                arcs.push(first - 80);
462	            }
463	        }
464	        while i < content.len() {
465	            arcs.push(read_oid_arc(content, &mut i)?);
466	        }
467	        Ok(arcs)
468	    }
469	
470	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
471	    /// continuation bytes and non-minimal encodings.
472	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
473	        let start = *i;
474	        let mut value = 0u64;
475	        loop {
476	            let b = *content
477	                .get(*i)
478	                .ok_or_else(|| "truncated OID arc".to_string())?;
479	            value = value
480	                .checked_mul(128)
481	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
482	                .ok_or_else(|| "OID arc overflow".to_string())?;
483	            *i += 1;
484	            if b & 0x80 == 0 {
485	                break;
486	            }
487	        }
488	        if *i - start > 1 && content[start] == 0x80 {
489	            return Err("non-minimal OID arc encoding".to_string());
490	        }
491	        Ok(value)
492	    }
493	
494	    fn arcs_to_string(arcs: &[u64]) -> String {
495	        arcs.iter()
496	            .map(u64::to_string)
497	            .collect::<Vec<_>>()
498	            .join(".")
499	    }
500	
501	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
502	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
503	        let name = match arcs {
504	            [2, 5, 4, 3] => "CN",
505	            [2, 5, 4, 4] => "SN",
506	            [2, 5, 4, 5] => "serialNumber",
507	            [2, 5, 4, 6] => "C",
508	            [2, 5, 4, 7] => "L",
509	            [2, 5, 4, 8] => "ST",
510	            [2, 5, 4, 9] => "STREET",
511	            [2, 5, 4, 10] => "O",
512	            [2, 5, 4, 11] => "OU",
513	            [2, 5, 4, 12] => "title",
514	            [2, 5, 4, 17] => "postalAddress",
515	            [2, 5, 4, 18] => "postalCode",
516	            [2, 5, 4, 20] => "telephoneNumber",
517	            [2, 5, 4, 42] => "givenName",
518	            [2, 5, 4, 43] => "initials",
519	            [2, 5, 4, 44] => "generationQualifier",
520	            [2, 5, 4, 46] => "dnQualifier",
521	            [2, 5, 4, 65] => "pseudonym",
522	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
523	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
524	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
525	            _ => return None,
526	        };
527	        Some(name)
528	    }
529	
530	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
531	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
532	        let s = match tag {
533	            0x0C => std::str::from_utf8(content)
534	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
535	                .to_string(),
536	            // ASCII-family strings: every byte is also its Unicode code point.
537	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
538	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
539	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
540	            0x1E => {
541	                if content.len() % 2 != 0 {
542	                    return Err("odd-length BMPString".to_string());
543	                }
544	                let units: Vec<u16> = content
545	                    .chunks_exact(2)
546	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
547	                    .collect();
548	                char::decode_utf16(units.iter().copied())
549	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
550	                    .collect::<Result<String, _>>()?
551	            }
552	            0x1C => {
553	                if content.len() % 4 != 0 {
554	                    return Err("invalid UniversalString length".to_string());
555	                }
556	                let mut s = String::new();
557	                for c in content.chunks_exact(4) {
558	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
559	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
560	                        return Err("invalid code point in UniversalString".to_string());
561	                    }
562	                    s.push(char::from_u32(cp).unwrap());
563	                }
564	                s
565	            }
566	            _ => {
567	                return Err(format!(
568	                    "unsupported attribute value string type (tag 0x{tag:02X})"
569	                ))
570	            }
571	        };
572	        Ok(s)
573	    }
574	
575	    /// RFC 4514 value escaping; everything above the ASCII control range
576	    /// (including CJK text) passes through unchanged.
577	    fn escape_value(value: &str) -> String {
578	        let mut out = String::with_capacity(value.len());
579	        let last = value.chars().count().saturating_sub(1);
580	        for (i, c) in value.chars().enumerate() {
581	            let at_edge = i == 0 || i == last;
582	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
583	                || (at_edge && (c == ' ' || c == '#'));
584	            if needs_backslash {
585	                out.push('\\');
586	                out.push(c);
587	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
588	                let mut buf = [0u8; 4];
589	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
590	                write!(out, "\\{b:02X}").unwrap();
591	            } else {
592	                out.push(c);
593	            }
594	        }
595	        out
596	    }
597	
598	    fn format_time(tlv: Tlv) -> Result<String, String> {
599	        let (y, mo, d, h, mi, se) = match tlv.tag {
600	            TAG_UTC_TIME => {
601	                let c = tlv.content;
602	                if c.len() != 13 || c[12] != b'Z' {
603	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
604	                }
605	                let digits = &c[..12];
606	                if !digits.iter().all(|b| b.is_ascii_digit()) {
607	                    return Err("non-numeric UTCTime".to_string());
608	                }
609	                let n = |a: usize, b: usize| -> u32 {
610	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
611	                };
612	                let yy = n(0, 1);
613	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
614	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
615	            }
616	            TAG_GENERALIZED_TIME => {
617	                let c = tlv.content;
618	                if c.len() != 15 || c[14] != b'Z' {
619	                    return Err(
620	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
621	                    );
622	                }
623	                let digits = &c[..14];
624	                if !digits.iter().all(|b| b.is_ascii_digit()) {
625	                    return Err("non-numeric GeneralizedTime".to_string());
626	                }
627	                let n = |a: usize, b: usize| -> u32 {
628	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
629	                };
630	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
631	            }
632	            other => return Err(format!("invalid time tag 0x{other:02X}")),
633	        };
634	        validate_datetime(y, mo, d, h, mi, se)?;
635	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
636	    }
637	
638	    fn validate_datetime(
639	        year: i32,
640	        month: u32,
641	        day: u32,
642	        hour: u32,
643	        minute: u32,
644	        second: u32,
645	    ) -> Result<(), String> {
646	        if !(1..=12).contains(&month) {
647	            return Err("invalid month in certificate time".to_string());
648	        }
649	        if hour > 23 || minute > 59 || second > 59 {
650	            return Err("invalid time of day in certificate time".to_string());
651	        }
652	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
653	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
654	        if day < 1 || day > days[(month - 1) as usize] {
655	            return Err("invalid day in certificate time".to_string());
656	        }
657	        Ok(())
658	    }
659	}
