1	//! End-to-end regression tests for SubjectPublicKeyInfo decoding when
2	//! running `chainview inspect <DER-FILE>`, locking the behavior already
3	//! implemented in `src/main.rs`.
4	//!
5	//! Public-key information never appears in the five displayed fields, but it
6	//! is still read in full: a structurally damaged SubjectPublicKeyInfo must
7	//! reject the whole certificate even though Subject/Issuer/validity are all
8	//! readable. The check is purely about the DER encoding — it does not verify
9	//! that the bytes form a key usable by any algorithm, never verifies a
10	//! signature and never judges trust.
11	//!
12	//! Coverage:
13	//! - AlgorithmIdentifier: absent parameters, an explicit NULL and any other
14	//!   single complete parameter TLV are all accepted; unknown OIDs that still
15	//!   decode are accepted (OIDs are not matched against an allow-list);
16	//! - subjectPublicKey BIT STRING: zero and nonzero unused-bits counts (with
17	//!   the declared low bits of the final data byte clear), and the existing
18	//!   acceptance of an empty bit string carrying only a zero count byte;
19	//! - structural rejection: missing algorithm/key, wrong element tags,
20	//!   trailing elements; missing/truncated/non-minimal OIDs; truncated or
21	//!   repeated parameters; and every malformed BIT STRING form (missing count
22	//!   byte, count > 7, nonzero count without data, set bits among the unused
23	//!   trailing bits).
24	//!
25	//! Every case drives the real `chainview` binary, so the public contract is
26	//! locked as a whole: on success exit code 0, empty stderr and exactly the
27	//! five fixed fields in their fixed order (their content never varies with
28	//! the public-key encoding); on malformed input exit code 2, completely empty
29	//! stdout and a `chainview: invalid DER certificate: <reason>` stderr.
30	//!
31	//! Certificates are built with the tiny zero-dependency DER constructor at
32	//! the bottom of this file, which lets individual encodings (including
33	//! truncated or non-minimal ones) be crafted byte for byte while every
34	//! enclosing wrapper keeps a correct length.
35	
36	use std::fs;
37	use std::path::PathBuf;
38	use std::process::{Command, Output};
39	use std::sync::atomic::{AtomicU64, Ordering};
40	
41	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
42	const FIXED_SUBJECT: &str = "CN=example.com";
43	const FIXED_ISSUER: &str = "CN=Test CA";
44	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
45	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
46	
47	// ----- Algorithm OID arcs --------------------------------------------------
48	
49	const RSA_ENCRYPTION: &[u64] = &[1, 2, 840, 113549, 1, 1, 1];
50	const EC_PUBLIC_KEY: &[u64] = &[1, 2, 840, 10045, 2, 1];
51	const P256_CURVE: &[u64] = &[1, 2, 840, 10045, 3, 1, 7];
52	
53	// ----- Success: AlgorithmIdentifier parameter forms ------------------------
54	
55	#[test]
56	fn spki_without_parameters_is_accepted() {
57	    // The parameters element is OPTIONAL: an AlgorithmIdentifier carrying
58	    // only the OID must be accepted exactly like one with an explicit NULL.
59	    let spki = spki_of(&alg_with_oid_only(RSA_ENCRYPTION), &default_key());
60	    let (out, _cert) = run_inspect("params-absent", &build_cert(&spki));
61	    assert_success(&out);
62	}
63	
64	#[test]
65	fn spki_with_explicit_null_parameters_is_accepted() {
66	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &default_key());
67	    let (out, _cert) = run_inspect("params-null", &build_cert(&spki));
68	    assert_success(&out);
69	}
70	
71	#[test]
72	fn spki_with_other_single_complete_parameter_value_is_accepted() {
73	    // Parameters need not be NULL: any one complete DER TLV is read and
74	    // accepted without being interpreted. An INTEGER parameter is one such
75	    // value; an embedded OID (the namedCurve form used by EC keys) is another.
76	    let integer_params = tlv(0x02, &[0x01, 0x00]); // INTEGER 0
77	    let spki = spki_of(
78	        &alg_with(RSA_ENCRYPTION, &integer_params),
79	        &default_key(),
80	    );
81	    let (out, _cert) = run_inspect("params-integer", &build_cert(&spki));
82	    assert_success(&out);
83	
84	    let oid_params = oid(P256_CURVE);
85	    let spki = spki_of(&alg_with(EC_PUBLIC_KEY, &oid_params), &default_key());
86	    let (out, _cert) = run_inspect("params-oid", &build_cert(&spki));
87	    assert_success(&out);
88	}
89	
90	#[test]
91	fn spki_with_unknown_but_decodable_algorithm_oid_is_accepted() {
92	    // The tool does not recognize 1.2.3.4 or 1.2.840.99999.7 as key
93	    // algorithms, but recognition is irrelevant: an OID that decodes by the
94	    // normal base-128 rules (99999 needs a multi-byte arc) is accepted, both
95	    // with and without parameters.
96	    let spki = spki_of(
97	        &alg_with_null_params(&[1, 2, 3, 4]),
98	        &default_key(),
99	    );
100	    let (out, _cert) = run_inspect("unknown-oid-null", &build_cert(&spki));
101	    assert_success(&out);
102	
103	    let spki = spki_of(
104	        &alg_with_oid_only(&[1, 2, 840, 99999, 7]),
105	        &default_key(),
106	    );
107	    let (out, _cert) = run_inspect("unknown-oid-longarc", &build_cert(&spki));
108	    assert_success(&out);
109	}
110	
111	// ----- Success: BIT STRING unused-bits encoding ----------------------------
112	
113	#[test]
114	fn public_key_with_zero_unused_bits_and_data_is_accepted() {
115	    // Zero unused bits over several data bytes, including a final 0xFF byte
116	    // whose low bits are all significant: nothing about the payload content
117	    // is judged (it need not be a real RSA/EC key DER).
118	    let key = bit_string(&[0x00, 0xAA, 0x55, 0xFF, 0x00]);
119	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &key);
120	    let (out, _cert) = run_inspect("bits-zero", &build_cert(&spki));
121	    assert_success(&out);
122	}
123	
124	#[test]
125	fn public_key_with_nonzero_unused_bits_and_clear_low_bits_is_accepted() {
126	    // Unused counts 1, 3 and 7 all succeed as long as the corresponding low
127	    // bits of the final data byte are zero. These encodings are checked; the
128	    // data itself is never required to be a usable public key.
129	    let cases: &[&[u8]] = &[
130	        &[0x01, 0x02], // 1 unused bit;  last byte low 1 bit  = 0
131	        &[0x03, 0xF8], // 3 unused bits; last byte low 3 bits = 000
132	        &[0x07, 0x80], // 7 unused bits; last byte low 7 bits = 0000000
133	    ];
134	    for (i, content) in cases.iter().enumerate() {
135	        let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &bit_string(content));
136	        let (out, _cert) = run_inspect(&format!("bits-nonzero-{i}"), &build_cert(&spki));
137	        assert_success(&out);
138	    }
139	}
140	
141	#[test]
142	fn public_key_empty_bit_string_with_zero_count_is_accepted() {
143	    // Existing behavior, pinned deliberately: a BIT STRING holding only the
144	    // zero unused-bits count (no data at all) is accepted. The check covers
145	    // encoding well-formedness, not whether a cryptographically usable key
146	    // exists.
147	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &bit_string(&[0x00]));
148	    let (out, _cert) = run_inspect("bits-empty", &build_cert(&spki));
149	    assert_success(&out);
150	}
151	
152	// ----- Failure: SubjectPublicKeyInfo structure -----------------------------
153	
154	#[test]
155	fn spki_missing_algorithm_identifier_is_rejected() {
156	    // The BIT STRING on its own, with no leading AlgorithmIdentifier
157	    // SEQUENCE, must not be skipped even though the key bytes are present.
158	    let spki = seq(&default_key());
159	    let (out, _cert) = run_inspect("spki-no-alg", &build_cert(&spki));
160	    assert_invalid_certificate(&out);
161	}
162	
163	#[test]
164	fn spki_missing_public_key_bit_string_is_rejected() {
165	    let spki = seq(&alg_with_null_params(RSA_ENCRYPTION));
166	    let (out, _cert) = run_inspect("spki-no-key", &build_cert(&spki));
167	    assert_invalid_certificate(&out);
168	}
169	
170	#[test]
171	fn spki_algorithm_identifier_with_wrong_tag_is_rejected() {
172	    // A bare OID in the AlgorithmIdentifier position is the wrong element
173	    // type: the identifier must itself be a SEQUENCE.
174	    let spki = seq(&concat(&[&oid(RSA_ENCRYPTION), &default_key()]));
175	    let (out, _cert) = run_inspect("spki-alg-tag", &build_cert(&spki));
176	    assert_invalid_certificate(&out);
177	}
178	
179	#[test]
180	fn spki_public_key_with_wrong_tag_is_rejected() {
181	    // An OCTET STRING where the subjectPublicKey BIT STRING must stand is a
182	    // type error, not a key that merely cannot be interpreted.
183	    let wrong_key = tlv(0x04, &[0x00, 0x01, 0x00]);
184	    let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &wrong_key);
185	    let (out, _cert) = run_inspect("spki-key-tag", &build_cert(&spki));
186	    assert_invalid_certificate(&out);
187	}
188	
189	#[test]
190	fn spki_with_extra_element_after_bit_string_is_rejected() {
191	    // Exactly two elements belong in SubjectPublicKeyInfo; a third TLV after
192	    // the key (here an INTEGER) makes the certificate corrupt.
193	    let extra = tlv(0x02, &[0x01, 0x2A]);
194	    let spki = seq(&concat(&[
195	        &alg_with_null_params(RSA_ENCRYPTION),
196	        &default_key(),
197	        &extra,
198	    ]));
199	    let (out, _cert) = run_inspect("spki-trailing", &build_cert(&spki));
200	    assert_invalid_certificate(&out);
201	}
202	
203	// ----- Failure: AlgorithmIdentifier contents -------------------------------
204	
205	#[test]
206	fn algorithm_identifier_missing_oid_is_rejected() {
207	    // An empty AlgorithmIdentifier SEQUENCE has no algorithm OID at all.
208	    let alg = seq(&[]);
209	    let spki = spki_of(&alg, &default_key());
210	    let (out, _cert) = run_inspect("alg-no-oid", &build_cert(&spki));
211	    assert_invalid_certificate(&out);
212	}
213	
214	#[test]
215	fn algorithm_oid_with_truncated_encoding_is_rejected() {
216	    // A single continuation byte 0x88 with no terminating byte promises
217	    // another base-128 byte that never arrives. The enclosing SEQUENCEs are
218	    // correctly sized, so the truncation is detected inside the OID itself.
219	    let truncated_oid = raw_tlv(0x06, &[0x01], &[0x88]);
220	    let alg = seq(&truncated_oid);
221	    let spki = spki_of(&alg, &default_key());
222	    let (out, _cert) = run_inspect("alg-oid-trunc", &build_cert(&spki));
223	    assert_invalid_certificate(&out);
224	}
225	
226	#[test]
227	fn algorithm_oid_with_nonminimal_encoding_is_rejected() {
228	    // Arc value 1 encoded as 0x80 0x01 (leading 0x80 continuation byte) is
229	    // not the shortest possible base-128 encoding and is invalid DER.
230	    let nonminimal_oid = raw_tlv(0x06, &[0x02], &[0x80, 0x01]);
231	    let alg = seq(&nonminimal_oid);
232	    let spki = spki_of(&alg, &default_key());
233	    let (out, _cert) = run_inspect("alg-oid-nonmin", &build_cert(&spki));
234	    assert_invalid_certificate(&out);
235	}
236	
237	#[test]
238	fn algorithm_parameter_with_truncated_value_is_rejected() {
239	    // The parameter TLV announces five content bytes but only three follow;
240	    // a half-read parameter cannot be salvaged by ignoring its tail.
241	    let truncated_params = raw_tlv(0x04, &[0x05], b"abc");
242	    let alg = seq(&concat(&[&oid(RSA_ENCRYPTION), &truncated_params]));
243	    let spki = spki_of(&alg, &default_key());
244	    let (out, _cert) = run_inspect("alg-params-trunc", &build_cert(&spki));
245	    assert_invalid_certificate(&out);
246	}
247	
248	#[test]
249	fn algorithm_identifier_with_multiple_parameters_is_rejected() {
250	    // Parameters are one OPTIONAL element, never a sequence of them: a NULL
251	    // followed by a second TLV must be rejected.
252	    let null_params = tlv(0x05, &[]);
253	    let second = tlv(0x02, &[0x01, 0x00]);
254	    let alg = seq(&concat(&[&oid(RSA_ENCRYPTION), &null_params, &second]));
255	    let spki = spki_of(&alg, &default_key());
256	    let (out, _cert) = run_inspect("alg-params-multi", &build_cert(&spki));
257	    assert_invalid_certificate(&out);
258	}
