282	#[test]
283	fn public_key_bit_string_nonzero_count_without_data_is_rejected() {
284	    // Declaring unused bits requires at least the byte they are unused in:
285	    // a lone nonzero count names bits that cannot exist.
286	    for (i, count) in [0x01u8, 0x07].into_iter().enumerate() {
287	        let spki = spki_of(
288	            &alg_with_null_params(RSA_ENCRYPTION),
289	            &bit_string(&[count]),
290	        );
291	        let (out, _cert) = run_inspect(&format!("bits-nodata-{i}"), &build_cert(&spki));
292	        assert_invalid_certificate(&out);
293	    }
294	}
