296	#[test]
297	fn public_key_bit_string_with_set_unused_tail_bits_is_rejected() {
298	    // With a nonzero count the named low bits of the final data byte must be
299	    // zero. Each case below has at least one of them set, so the encoding
300	    // lies about its padding even though the rest of the certificate parses.
301	    let cases: &[&[u8]] = &[
302	        &[0x01, 0x01], // 1 unused bit;  low 1 bit set
303	        &[0x02, 0x03], // 2 unused bits; both low bits set
304	        &[0x03, 0xF9], // 3 unused bits; lowest of them set (...001)
305	        &[0x07, 0x81], // 7 unused bits; lowest bit set
306	        &[0x03, 0x00, 0x01], // padding is judged on the FINAL byte only,
307	                             // and that final byte still has a set low bit
308	    ];
309	    for (i, content) in cases.iter().enumerate() {
310	        let spki = spki_of(&alg_with_null_params(RSA_ENCRYPTION), &bit_string(content));
311	        let (out, _cert) = run_inspect(&format!("bits-tailset-{i}"), &build_cert(&spki));
312	        assert_invalid_certificate(&out);
313	    }
314	}
315	
316	// ----- Assertions / process plumbing --------------------------------------
317	
318	/// A successful inspect must print exactly the five fixed fields in their
319	/// fixed order; none of their content varies with the SPKI encoding, and
320	/// stderr stays empty.
321	fn assert_success(out: &Output) {
322	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
323	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
324	    assert_eq!(
325	        lossy(&out.stdout),
326	        format!(
327	            "Subject: {FIXED_SUBJECT}\n\
328	             Issuer: {FIXED_ISSUER}\n\
329	             Serial Number: {FIXED_SERIAL}\n\
330	             Not Before: {FIXED_NOT_BEFORE}\n\
331	             Not After: {FIXED_NOT_AFTER}\n"
332	        )
333	    );
334	}
335	
336	/// Every malformed-input case shares the documented contract: exit code 2,
337	/// nothing at all on stdout (parse failure precedes every print), and the
338	/// fixed invalid-certificate prefix on stderr with a non-empty reason after
339	/// it. The reason's exact wording is intentionally not pinned.
340	fn assert_invalid_certificate(out: &Output) {
341	    assert_eq!(
342	        out.status.code(),
343	        Some(2),
344	        "stdout={} stderr={}",
345	        lossy(&out.stdout),
346	        lossy(&out.stderr)
347	    );
348	    assert!(
349	        out.stdout.is_empty(),
350	        "stdout must be empty on failure, got: {}",
351	        lossy(&out.stdout)
352	    );
353	    let stderr = lossy(&out.stderr);
354	    assert!(
355	        stderr.starts_with("chainview: invalid DER certificate: "),
356	        "unexpected stderr: {stderr}"
357	    );
358	    assert!(
359	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
360	        "missing error reason in stderr: {stderr}"
361	    );
362	}
363	
364	fn lossy(bytes: &[u8]) -> String {
365	    String::from_utf8_lossy(bytes).into_owned()
366	}
367	
368	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
369	    let cert = TempCert::new(tag, data);
370	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
371	        .arg("inspect")
372	        .arg(&cert.path)
373	        .output()
374	        .expect("running chainview");
375	    (output, cert)
376	}
377	
378	struct TempCert {
379	    path: PathBuf,
380	}
381	
382	impl TempCert {
383	    fn new(tag: &str, data: &[u8]) -> Self {
384	        static COUNTER: AtomicU64 = AtomicU64::new(0);
385	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
386	        let path = std::env::temp_dir().join(format!(
387	            "chainview-spki-test-{}-{tag}-{unique}.der",
388	            std::process::id()
389	        ));
390	        fs::write(&path, data).expect("writing temp certificate");
391	        TempCert { path }
392	    }
393	}
394	
395	impl Drop for TempCert {
396	    fn drop(&mut self) {
397	        let _ = fs::remove_file(&self.path);
398	    }
399	}
400	
401	// ----- Certificate / DER construction -------------------------------------
402	//
403	// Only the structural pieces needed here. Lengths are always emitted in the
404	// minimal DER form, except where a test injects hand-written length or
405	// content bytes (truncated or non-minimal OID arcs, a truncated parameter);
406	// such bytes are always wrapped by correctly sized SEQUENCEs so rejection is
407	// proven to come from the element under test.
408	
409	/// Assemble a complete, parseable v1 DER certificate with fixed names,
410	/// serial, validity and signature material around the supplied
411	/// SubjectPublicKeyInfo TLV.
412	fn build_cert(spki: &[u8]) -> Vec<u8> {
413	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
414	    let validity = seq(&concat(&[
415	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
416	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
417	    ]));
418	    let subject = simple_cn_name("example.com");
419	    let issuer = simple_cn_name("Test CA");
420	
421	    let tbs = seq(&concat(&[
422	        &serial,
423	        &signature_algorithm(),
424	        &issuer,
425	        &validity,
426	        &subject,
427	        spki,
428	    ]));
429	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
430	}
431	
432	fn signature_algorithm() -> Vec<u8> {
433	    // sha256WithRSAEncryption with explicit NULL parameters.
434	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
435	}
436	
437	/// SubjectPublicKeyInfo ::= SEQUENCE { algorithm AlgorithmIdentifier,
438	/// subjectPublicKey BIT STRING }.
439	fn spki_of(alg: &[u8], key: &[u8]) -> Vec<u8> {
440	    seq(&concat(&[alg, key]))
441	}
442	
443	fn alg_with_oid_only(arcs: &[u64]) -> Vec<u8> {
444	    seq(&oid(arcs))
445	}
446	
447	fn alg_with_null_params(arcs: &[u64]) -> Vec<u8> {
448	    alg_with(arcs, &tlv(0x05, &[]))
449	}
450	
451	/// AlgorithmIdentifier with one caller-supplied complete parameter TLV.
452	fn alg_with(arcs: &[u64], params: &[u8]) -> Vec<u8> {
453	    seq(&concat(&[&oid(arcs), params]))
454	}
455	
456	/// BIT STRING carrying the supplied content (unused-bits count plus data).
457	fn bit_string(content: &[u8]) -> Vec<u8> {
458	    tlv(0x03, content)
459	}
460	
461	/// A small, well-formed key BIT STRING: zero unused bits, two data bytes.
462	fn default_key() -> Vec<u8> {
463	    bit_string(&[0x00, 0x01, 0x00])
464	}
465	
466	fn simple_cn_name(cn: &str) -> Vec<u8> {
467	    let atv = seq(&concat(&[&oid(&[2, 5, 4, 3]), &tlv(0x0C, cn.as_bytes())]));
468	    let rdn = tlv(0x31, &atv); // SET { CN=... }
469	    tlv(0x30, &rdn) // SEQUENCE { RDN }
470	}
471	
472	/// TLV with caller-supplied length bytes; used to forge truncated encodings.
473	fn raw_tlv(tag: u8, len_bytes: &[u8], content: &[u8]) -> Vec<u8> {
474	    let mut out = vec![tag];
475	    out.extend_from_slice(len_bytes);
476	    out.extend_from_slice(content);
477	    out
478	}
479	
480	fn oid(arcs: &[u64]) -> Vec<u8> {
481	    assert!(arcs.len() >= 2);
482	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
483	    for &arc in &arcs[2..] {
484	        content.extend_from_slice(&oid_arc(arc));
485	    }
486	    tlv(0x06, &content)
487	}
488	
489	fn oid_arc(mut value: u64) -> Vec<u8> {
490	    let mut out = vec![(value % 128) as u8];
491	    value /= 128;
492	    while value > 0 {
493	        out.push(0x80 | (value % 128) as u8);
494	        value /= 128;
495	    }
496	    out.reverse();
497	    out
498	}
499	
500	fn seq(content: &[u8]) -> Vec<u8> {
501	    tlv(0x30, content)
502	}
503	
504	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
505	    let mut out = vec![tag];
506	    out.extend_from_slice(&der_len(content.len()));
507	    out.extend_from_slice(content);
508	    out
509	}
510	
511	fn der_len(n: usize) -> Vec<u8> {
512	    if n < 0x80 {
513	        vec![n as u8]
514	    } else {
515	        let mut body = Vec::new();
516	        let mut v = n;
517	        while v > 0 {
518	            body.push((v & 0xFF) as u8);
519	            v >>= 8;
520	        }
521	        body.reverse();
522	        let mut out = vec![0x80 | body.len() as u8];
523	        out.extend_from_slice(&body);
524	        out
525	    }
526	}
527	
528	fn concat(parts: &[&[u8]]) -> Vec<u8> {
529	    let mut out = Vec::new();
530	    for part in parts {
531	        out.extend_from_slice(part);
532	    }
533	    out
534	}
