            match maybe_bool.content {
                [0xFF] => {}
                [0x00] => {
                    return Err(
                        "explicit DER encoding of critical DEFAULT FALSE is not allowed"
                            .to_string()
                    )
                }
                _ => {
                    return Err("invalid DER encoding of extension critical BOOLEAN".to_string())
                }
