#[test]
fn extension_with_truncated_oid_is_rejected() {
    // 0x88 promises another base-128 byte that never arrives; the wrapper
    // lengths around it are all correct.
    let body = tlv(
        0x30,
        &concat(&[&tlv(0x06, &[0x88]), &tlv(0x04, &[0x00])]),
